using UnityEngine;

public class IceBolt : MonoBehaviour
{
    public float freezeChance = 0.25f;

    void Start() {
        // Initialization if needed
    }

    public void CastIceBolt(GameObject target)
    {
        // Logic to cast Ice Bolt
        if (Random.value <= freezeChance)
        {
            // Apply freeze status to target
            target.GetComponent<Stats>().StatusDamage("Freeze", 2, 0);
        }
    }
}
